// Assigns a new value to the sidebag's existing binding of sym (nothing happens when unbound); returns Void.
CRef CSidebag::RefSetBinding(int sym, CRef *pref)
{
    CVarb *pb;
    for (pb = pbindingFirst.p; pb; pb = pb->pnext.p) {
        if (pb->sym == sym) {
            CRef ref;
            pb->ref = *pref;
            ref.Decref();
            ref.InitTag(0x24);
            return ref;
        }
    }
    {
        CRef ref;
        ref.Decref();
        ref.InitTag(0x24);
        return ref;
    }
}

